create or replace function app_private.export_view(p_export uuid,p_actor uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare e app_private.export_jobs%rowtype;s app_private.export_states%rowtype;begin select * into e from app_private.export_jobs where id=p_export and requester_id=p_actor;if e.id is null then raise exception 'NOT_FOUND';end if;perform app_private.export_assert_scope(p_actor,e.session_id,e.kind,e.filters,e.columns);select * into s from app_private.export_states where export_id=e.id;if s.state<>'ready'and exists(select 1 from app_private.outbox_jobs j where j.id=s.job_id and j.state='failed')then s.state:='failed';end if;return jsonb_build_object('export_id',e.id,'kind',e.kind,'state',s.state,'grain',e.grain,'columns',e.columns,'filters',e.filters,'snapshot_at',e.snapshot_at,'as_of',e.as_of,'row_count',e.row_count,'expires_at',e.expires_at,'version',s.version,'can_download',s.state='ready'and e.expires_at>now(),'download_path',case when s.state='ready'and e.expires_at>now()then '/api/v1/exports/'||e.id||'/content'else null end,'safe_error_code',coalesce(s.safe_error_code,(select last_error_code from app_private.outbox_jobs where id=s.job_id)));end$$;
notify pgrst,'reload schema';
